@pytest.mark.parametrize("test_case", _PARAM_CASES, ids=_PARAM_IDS)
def test_authentication_scenarios(api_client, test_case):
    """
    Test authentication scenarios for /store/order endpoint.
    """
    # Prepare headers and data
    data = {
        "id": test_case.get("id"),
        "petId": test_case.get("petId"),
        "quantity": test_case.get("quantity", 1),
        "shipDate": test_case.get("shipDate"),
        "status": test_case.get("status"),
        "complete": test_case.get("complete", False)
    }

    # Test with missing auth
    headers = {
        "Content-Type": "application/json"
    }
    response = api_client.post("/store/order", data=json.dumps(data), headers=headers)
    assert response.status_code == 401, "Expected 401 Unauthorized when no auth provided"

    # Test with invalid auth
    headers["Authorization"] = "Bearer invalid_token"
    response = api_client.post("/store/order", data=json.dumps(data), headers=headers)
    assert response.status_code == 401, "Expected 401 Unauthorized with invalid token"

    # Test with valid auth
    headers["Authorization"] = f"Bearer {test_case.get('auth', 'valid_token')}"
    response = api_client.post("/store/order", data=json.dumps(data), headers=headers)
    assert response.status_code == test_case["statusCode"], f"Unexpected status code: {response.status_code}"

